CREATE EXTENSION pg_walinspect;
SELECT pg_current_wal_lsn() AS antes \gset
UPDATE productos SET stock = stock - 1 WHERE sku = 'COMP-003';
SELECT pg_current_wal_lsn() AS despues \gset
SELECT :'antes' AS antes, :'despues' AS despues,
       pg_wal_lsn_diff(:'despues', :'antes') AS bytes;
SELECT start_lsn, resource_manager, record_type, record_length
FROM pg_get_wal_records_info(:'antes', :'despues');

SELECT pg_current_wal_lsn() AS lsn_actual,
       pg_walfile_name(pg_current_wal_lsn()) AS archivo;
SELECT pg_wal_lsn_diff('0/3001330', '0/3000000') AS bytes,
       '0/3001330'::pg_lsn - '0/3000000'::pg_lsn AS con_resta,
       '0/3000000'::pg_lsn + 16777216 AS un_segmento_despues;
SELECT pg_size_pretty(pg_wal_lsn_diff('3/2A5C2B10', '3/1F0A2000')) AS atraso;
SELECT pg_walfile_name_offset('0/3001330');

\d pg_stat_replication
SELECT pg_is_in_recovery() AS soy_replica;
SELECT name, setting, context
FROM pg_settings
WHERE name IN ('wal_level', 'max_wal_senders', 'max_replication_slots', 'hot_standby', 'wal_keep_size')
ORDER BY name;

SELECT count(*) AS slots FROM pg_replication_slots;
SELECT * FROM pg_create_physical_replication_slot('replica_valpo', true);
SELECT slot_name, slot_type, active, restart_lsn, wal_status
FROM pg_replication_slots;
SELECT slot_name,
       pg_size_pretty(pg_wal_lsn_diff(pg_current_wal_lsn(), restart_lsn)) AS wal_retenido
FROM pg_replication_slots;
SELECT pg_drop_replication_slot('replica_valpo');
SHOW max_slot_wal_keep_size;
SHOW idle_replication_slot_timeout;

ALTER SYSTEM SET synchronous_standby_names = 'FIRST 1 (replica_stgo, replica_valpo)';
ALTER SYSTEM SET synchronous_standby_names = 'ANY 2 (replica_stgo, replica_valpo, replica_conce)';
ALTER SYSTEM SET synchronous_standby_names = 'ANY 2 replica_stgo, replica_valpo';
SELECT name, setting, applied FROM pg_file_settings
WHERE name = 'synchronous_standby_names';
BEGIN;
SET LOCAL synchronous_commit = remote_apply;
SHOW synchronous_commit;
COMMIT;

